import React, { useState } from 'react';
import '../styles/theme.css';

export default function Transactions() {
  const [activeTab, setActiveTab] = useState('farmers');
  const [searchQuery, setSearchQuery] = useState('');

  const farmersList = [
    { name: 'Ramesh Patel', village: 'Rau', purchases: '₹ 18,50,000', paid: '₹ 15,00,000', outstanding: '₹ 3,50,000', status: 'Pending' },
    { name: 'Suresh Yadav', village: 'Betma', purchases: '₹ 9,20,000', paid: '₹ 9,20,000', outstanding: '₹ 0', status: 'Cleared' },
    { name: 'Mohan Verma', village: 'Depalpur', purchases: '₹ 12,80,000', paid: '₹ 10,00,000', outstanding: '₹ 2,80,000', status: 'Pending' }
  ];

  const partiesList = [
    { name: 'Shree Ji Flour Mill', type: 'Buyer / Mill', purchases: '₹ 45,00,000', paid: '₹ 40,00,000', outstanding: '₹ 5,00,000' },
    { name: 'Malwa Agro Traders', type: 'Wholesale Buyer', purchases: '₹ 28,00,000', paid: '₹ 28,00,000', outstanding: '₹ 0' }
  ];

  return (
    <div style={{ width: '100%', maxWidth: '1100px', margin: '0 auto', fontFamily: 'Segoe UI, sans-serif' }}>
      
      {/* Header & Tabs */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
        <div>
          <h2 style={{ color: '#1B4D3E', margin: 0, fontSize: '22px' }}>Transactions & Parties Ledger</h2>
          <p style={{ color: '#718096', fontSize: '13px', margin: '4px 0 0 0' }}>Manage farmer accounts, grain buyers, and financial ledgers.</p>
        </div>
        <button style={primaryBtn}>+ Add New Party</button>
      </div>

      {/* Tabs Switcher */}
      <div style={{ display: 'flex', gap: '10px', marginBottom: '20px', borderBottom: '1px solid #E2E8F0', paddingBottom: '12px' }}>
        <button 
          onClick={() => setActiveTab('farmers')} 
          style={activeTab === 'farmers' ? activeTabStyle : inactiveTabStyle}
        >
          🌾 Farmers Accounts
        </button>
        <button 
          onClick={() => setActiveTab('parties')} 
          style={activeTab === 'parties' ? activeTabStyle : inactiveTabStyle}
        >
          🏢 Parties / Companies
        </button>
      </div>

      {/* Search Bar */}
      <div style={{ marginBottom: '20px' }}>
        <input 
          type="text" 
          placeholder={`Search ${activeTab === 'farmers' ? 'farmer name or village' : 'party name'}...`} 
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          style={searchInputStyle}
        />
      </div>

      {/* Data Table / Cards Container */}
      <div style={{ background: '#FFF', borderRadius: '12px', boxShadow: '0 4px 12px rgba(0,0,0,0.04)', border: '1px solid #E2E8F0', overflow: 'hidden' }}>
        
        {activeTab === 'farmers' ? (
          <div>
            {farmersList.map((item, index) => (
              <div key={index} style={rowCardStyle}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
                  <div style={avatarStyle}>{item.name.split(' ').map(n => n[0]).join('')}</div>
                  <div>
                    <div style={{ fontWeight: 'bold', fontSize: '15px', color: '#2D3748' }}>{item.name}</div>
                    <div style={{ fontSize: '12px', color: '#718096' }}>Village: {item.village}</div>
                  </div>
                </div>

                <div style={{ display: 'flex', gap: '40px', alignItems: 'center' }}>
                  <div>
                    <div style={{ fontSize: '11px', color: '#718096' }}>Total Purchase</div>
                    <div style={{ fontSize: '14px', fontWeight: 'bold', color: '#2D3748' }}>{item.purchases}</div>
                  </div>
                  <div>
                    <div style={{ fontSize: '11px', color: '#718096' }}>Amount Paid</div>
                    <div style={{ fontSize: '14px', fontWeight: 'bold', color: '#27AE60' }}>{item.paid}</div>
                  </div>
                  <div>
                    <div style={{ fontSize: '11px', color: '#718096' }}>Outstanding</div>
                    <div style={{ fontSize: '14px', fontWeight: 'bold', color: item.status === 'Cleared' ? '#27AE60' : '#E53E3E' }}>
                      {item.outstanding}
                    </div>
                  </div>
                  <button style={actionBtnStyle}>View Ledger</button>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div>
            {partiesList.map((item, index) => (
              <div key={index} style={rowCardStyle}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
                  <div style={{ ...avatarStyle, background: '#2B6CB0' }}>{item.name[0]}</div>
                  <div>
                    <div style={{ fontWeight: 'bold', fontSize: '15px', color: '#2D3748' }}>{item.name}</div>
                    <div style={{ fontSize: '12px', color: '#718096' }}>Type: {item.type}</div>
                  </div>
                </div>

                <div style={{ display: 'flex', gap: '40px', alignItems: 'center' }}>
                  <div>
                    <div style={{ fontSize: '11px', color: '#718096' }}>Total Sales</div>
                    <div style={{ fontSize: '14px', fontWeight: 'bold', color: '#2D3748' }}>{item.purchases}</div>
                  </div>
                  <div>
                    <div style={{ fontSize: '11px', color: '#718096' }}>Received</div>
                    <div style={{ fontSize: '14px', fontWeight: 'bold', color: '#27AE60' }}>{item.paid}</div>
                  </div>
                  <div>
                    <div style={{ fontSize: '11px', color: '#718096' }}>Balance Due</div>
                    <div style={{ fontSize: '14px', fontWeight: 'bold', color: '#E53E3E' }}>{item.outstanding}</div>
                  </div>
                  <button style={actionBtnStyle}>View Ledger</button>
                </div>
              </div>
            ))}
          </div>
        )}

      </div>

    </div>
  );
}

const primaryBtn = { background: '#1B4D3E', color: '#FFF', border: 'none', padding: '10px 18px', borderRadius: '8px', fontWeight: 'bold', fontSize: '13px', cursor: 'pointer' };
const activeTabStyle = { background: '#1B4D3E', color: '#FFF', border: 'none', padding: '10px 20px', borderRadius: '8px', fontWeight: 'bold', fontSize: '13px', cursor: 'pointer' };
const inactiveTabStyle = { background: '#EDF2F7', color: '#4A5568', border: 'none', padding: '10px 20px', borderRadius: '8px', fontWeight: '600', fontSize: '13px', cursor: 'pointer' };
const searchInputStyle = { width: '100%', padding: '12px 16px', borderRadius: '8px', border: '1px solid #CBD5E0', background: '#FFF', fontSize: '14px', boxSizing: 'border-box', outline: 'none' };
